use burn::backend::wgpu::{CubeBackend, WgpuRuntime};
use burn::prelude::*;
use burn::nn::conv::{Conv2dConfig, Conv2d};
use burn::nn::BatchNormConfig;
use burn::module::Initializer;
use burn_fusion::Fusion;

// NOTE: Probe contract requires fn body(), no main.

fn manual_batch_norm_f16<B: Backend>(
    x: Tensor<B, 4>,
    mean: Tensor<B, 4>,
    var: Tensor<B, 4>,
    gamma: Tensor<B, 4>,
    beta: Tensor<B, 4>,
    eps: f32,
) -> Tensor<B, 4> {
    // (x - mean) / sqrt(var + eps) * gamma + beta
    let eps_t = B::float_scalar(eps);
    (x - mean) / (var + eps_t).sqrt() * gamma + beta
}

// helper deterministic f16-ish input via simple formula
fn make_input<B: Backend>(batch: usize, ch: usize, h: usize, w: usize) -> Tensor<B, 4> {
    let n = batch * ch * h * w;
    let mut v = Vec::<f32>::with_capacity(n);
    for idx in 0..n {
        let x = idx as f32;
        v.push((x * 7.13).sin() * 0.5);
    }
    let t = Tensor::<B, 1>::from_floats(v);
    t.reshape([batch, ch, h, w])
}

fn make_params<B: Backend>(ch: usize, seed: u64, scale: f32) -> Tensor<B, 4> {
    let mut v = Vec::<f32>::with_capacity(ch);
    // simple LCG-ish deterministic pseudo-random
    let mut s = seed;
    for _ in 0..ch {
        s = s.wrapping_mul(6364136223846793005).wrapping_add(1);
        let r = ((s >> 32) as u32) as f32 / (u32::MAX as f32);
        v.push((r - 0.5) * 2.0 * scale);
    }
    Tensor::<B, 1>::from_floats(v).reshape([1, ch, 1, 1])
}

fn run_branch<B: Backend>(
    input: Tensor<B, 4>,
    conv: Conv2d<B>,
    mean: Tensor<B, 4>,
    var: Tensor<B, 4>,
    gamma: Tensor<B, 4>,
    beta: Tensor<B, 4>,
    eps: f32,
) -> Tensor<B, 4> {
    let y = conv.forward(input);
    manual_batch_norm_f16(y, mean, var, gamma, beta, eps)
}

pub fn body() {
    // Spatial dims: 16x16, input channels 64, output channels 256
    type Fused = Fusion<CubeBackend<WgpuRuntime, half::f16, i32, u8>>;
    type Unfused = CubeBackend<WgpuRuntime, half::f16, i32, u8>;

    let device = WgpuRuntime::new().unwrap();
    let fused_backend = CubeBackend::new(device.clone());
    let unfused_backend = CubeBackend::new(device);

    let fused: Fused = Fusion::new(fused_backend);
    let unfused: Unfused = unfused_backend;

    let (batch, in_ch, out_ch, h, w) = (1usize, 64usize, 256usize, 16usize, 16usize);

    let input_f16 = make_input::<Fused>(batch, in_ch, h, w).to_device(&fused);
    let input_u16 = make_input::<Unfused>(batch, in_ch, h, w).to_device(&unfused);

    // conv: 1x1, no bias
    let conv_cfg = Conv2dConfig::new(in_ch, out_ch, [1, 1]).with_bias(false);
    let conv_a_f = Conv2d::<Fused>::init(conv_cfg.clone(), &mut Default::default());
    let conv_b_f = Conv2d::<Fused>::init(conv_cfg.clone(), &mut Default::default());
    let conv_a_u = Conv2d::<Unfused>::init(conv_cfg.clone(), &mut Default::default());
    let conv_b_u = Conv2d::<Unfused>::init(conv_cfg, &mut Default::default());

    // overwrite weights deterministically with seeds to match input/expected structure
    // This uses the layer's weight tensor accessor.
    let scale_w = (2.0f32 / 64.0f32).sqrt();
    let w_a_f = make_params::<Fused>(out_ch, 1, scale_w).reshape([out_ch, in_ch, 1, 1]);
    let w_b_f = make_params::<Fused>(out_ch, 2, scale_w).reshape([out_ch, in_ch, 1, 1]);
    conv_a_f.set_weight(w_a_f);
    conv_b_f.set_weight(w_b_f);

    let w_a_u = make_params::<Unfused>(out_ch, 1, scale_w).reshape([out_ch, in_ch, 1, 1]);
    let w_b_u = make_params::<Unfused>(out_ch, 2, scale_w).reshape([out_ch, in_ch, 1, 1]);
    conv_a_u.set_weight(w_a_u);
    conv_b_u.set_weight(w_b_u);

    // manual BN params
    let mean_a_f = make_params::<Fused>(out_ch, 301, 0.5);
    let mean_b_f = make_params::<Fused>(out_ch, 302, 0.5);
    let var_a_f = make_params::<Fused>(out_ch, 401, 0.5);
    let var_b_f = make_params::<Fused>(out_ch, 402, 0.5);
    let gamma_a_f = make_params::<Fused>(out_ch, 101, 1.0).add(1.0);
    let gamma_b_f = make_params::<Fused>(out_ch, 102, 1.0).add(1.0);
    let beta_a_f = make_params::<Fused>(out_ch, 201, 0.3);
    let beta_b_f = make_params::<Fused>(out_ch, 202, 0.3);

    let mean_a_u = make_params::<Unfused>(out_ch, 301, 0.5);
    let mean_b_u = make_params::<Unfused>(out_ch, 302, 0.5);
    let var_a_u = make_params::<Unfused>(out_ch, 401, 0.5);
    let var_b_u = make_params::<Unfused>(out_ch, 402, 0.5);
    let gamma_a_u = make_params::<Unfused>(out_ch, 101, 1.0).add(1.0);
    let gamma_b_u = make_params::<Unfused>(out_ch, 102, 1.0).add(1.0);
    let beta_a_u = make_params::<Unfused>(out_ch, 201, 0.3);
    let beta_b_u = make_params::<Unfused>(out_ch, 202, 0.3);

    let eps = 1e-5f32;

    // fused forward: two branches and sum
    let a_f = run_branch::<Fused>(input_f16.clone(), conv_a_f, mean_a_f, var_a_f, gamma_a_f, beta_a_f, eps);
    let b_f = run_branch::<Fused>(input_f16, conv_b_f, mean_b_f, var_b_f, gamma_b_f, beta_b_f, eps);
    let fused_out = a_f + b_f;

    // unfused reference
    let a_u = run_branch::<Unfused>(input_u16.clone(), conv_a_u, mean_a_u, var_a_u, gamma_a_u, beta_a_u, eps);
    let b_u = run_branch::<Unfused>(input_u16, conv_b_u, mean_b_u, var_b_u, gamma_b_u, beta_b_u, eps);
    let unfused_out = a_u + b_u;

    // compare: bring to host floats
    let fused_vals = fused_out.to_data().value;
    let unfused_vals = unfused_out.to_data().value;

    let mut max_abs = 0.0f32;
    let mut any_nonfinite = false;
    let mut first_bad_idx: i32 = -1;
    for (i, (&f, &u)) in fused_vals.iter().zip(unfused_vals.iter()).enumerate() {
        let f32v = f.to_f32();
        let u32v = u.to_f32();
        if !f32v.is_finite() || !u32v.is_finite() {
            any_nonfinite = true;
            if first_bad_idx < 0 { first_bad_idx = i as i32; }
        }
        let d = (f32v - u32v).abs();
        if d > max_abs { max_abs = d; }
    }

    // record
    let _ = probe_scalar("fused_any_nonfinite", if any_nonfinite {1.0} else {0.0});
    let _ = probe_scalar("fused_first_bad_idx", first_bad_idx as f32);
    let _ = probe_scalar("max_abs_diff", max_abs);
    if fused_vals.len() > 0 {
        let f0 = fused_vals[0].to_f32();
        let u0 = unfused_vals[0].to_f32();
        let _ = probe_scalar("fused_elem0", f0);
        let _ = probe_scalar("unfused_elem0", u0);
    }
}
